// Italian texts of catalog.mjs: [English text, Italian text], in catalog order. The English side must match the T()
// text exactly (the build names any text without a translation and any entry whose English text changed or went
// away). Terms follow the app (src/Filee.App/Assets/i18n/it.json): preset, motore / motori facoltativi (engines),
// donut, fetta (slice), Cartelle monitorate (watch folders), area di rilascio (drop zone), integrato (built in),
// Impostazioni → Motori → Usa la mia copia…, preset names as in the app (Comprimi PDF, Unisci PDF, Vettorializza in
// SVG, Disegno al tratto in SVG, Estrai fotogrammi…); tu, like the app.

import { dictionary } from './dictionary.mjs';

export default dictionary([
  // Engines
  [`video and audio, subtitle extraction and saving HEIC`,
    `video e audio, estrazione dei sottotitoli e salvataggio in HEIC`],
  [`older office formats such as DOC, PPT and ODT`, `formati Office più vecchi come DOC, PPT e ODT`],
  [`rare e-book formats and MOBI/AZW3 output`, `formati di e-book rari e output MOBI/AZW3`],
  [`EPS and PostScript`, `EPS e PostScript`],
  [`LaTeX, Org, AsciiDoc and other markup, Word → Markdown and Markdown → slides`,
    `LaTeX, Org, AsciiDoc e altri linguaggi di markup, Word → Markdown e Markdown → slide`],

  // Options
  [`quality`, `qualità`],
  [`Adjustable quality for JPG, WEBP and AVIF: JPG saves at 90 % by default, and a JPG 70 % preset makes smaller files.`,
    `Qualità regolabile per JPG, WEBP e AVIF: per impostazione predefinita JPG salva al 90 %, e un preset JPG 70 % crea file più piccoli.`],
  [`resize`, `ridimensionamento`],
  [`Resize while converting, by percentage (for example half size) or to a maximum long edge.`,
    `Ridimensiona durante la conversione, in percentuale (per esempio a metà) o fino a un lato lungo massimo.`],
  [`DPI`, `DPI`],
  [`Set the DPI written into the image, for example 300 for print.`,
    `Imposta i DPI scritti nell'immagine, per esempio 300 per la stampa.`],
  [`grayscale`, `scala di grigi`],
  [`A grayscale preset makes black-and-white copies.`, `Un preset in scala di grigi crea copie in bianco e nero.`],
  [`metadata`, `metadati`],
  [`Metadata (EXIF, XMP, colour profile) is kept by default and can be removed for privacy.`,
    `I metadati (EXIF, XMP, profilo colore) vengono mantenuti per impostazione predefinita e si possono rimuovere per la privacy.`],
  [`ICO sizes`, `dimensioni ICO`],
  [`ICO files hold 256, 128, 64, 48, 32 and 16 px by default; the sizes can be changed in the preset.`,
    `Per impostazione predefinita i file ICO contengono 256, 128, 64, 48, 32 e 16 px; le dimensioni si possono cambiare nel preset.`],
  [`TIFF compression`, `compressione TIFF`],
  [`TIFF compression can be chosen (LZW by default).`, `La compressione TIFF si può scegliere (LZW per impostazione predefinita).`],
  [`white background`, `sfondo bianco`],
  [`JPG has no transparency, so transparent areas are filled with white.`,
    `JPG non ha trasparenza, quindi le aree trasparenti vengono riempite di bianco.`],
  [`merge into one PDF`, `unione in un unico PDF`],
  [`The merge preset combines all dropped files into one PDF.`,
    `Il preset di unione combina tutti i file rilasciati in un unico PDF.`],
  [`split pages`, `divisione delle pagine`],
  [`The split preset saves every page as its own PDF in a subfolder.`,
    `Il preset di divisione salva ogni pagina come PDF a sé in una sottocartella.`],
  [`rotate & flip`, `rotazione e capovolgimento`],
  [`Rotate and flip presets turn images left, right or 180° and mirror them, after the photo's own orientation.`,
    `I preset di rotazione e capovolgimento ruotano le immagini a sinistra, a destra o di 180° e le specchiano, dopo l'orientamento proprio della foto.`],
  [`Trace to SVG`, `Vettorializza in SVG`],
  [`Two presets trace a picture into vector shapes: Trace to SVG in up to 64 colours, and Line art to SVG in black for logos, signatures and scans. No other program is needed.`,
    `Due preset trasformano un'immagine in forme vettoriali: Vettorializza in SVG con un massimo di 64 colori, e Disegno al tratto in SVG in nero per loghi, firme e scansioni. Non serve nessun altro programma.`],
  [`remove background`, `rimozione dello sfondo`],
  [`The Remove background preset makes a plain backdrop transparent: the paper behind a signature or stamp, the backdrop of a logo.`,
    `Il preset Rimuovi sfondo rende trasparente uno sfondo uniforme: la carta dietro una firma o un timbro, lo sfondo di un logo.`],
  [`page ranges`, `intervalli di pagine`],
  [`Page ranges such as 1-3,5 limit the conversion to the pages you need.`,
    `Gli intervalli di pagine come 1-3,5 limitano la conversione alle pagine che ti servono.`],
  [`render DPI`, `DPI di rendering`],
  [`Pages are rendered at 150 DPI by default; choose 300 DPI for print quality.`,
    `Per impostazione predefinita le pagine vengono renderizzate a 150 DPI; scegli 300 DPI per la qualità di stampa.`],
  [`one long image`, `un'unica immagine lunga`],
  [`The Long image preset stacks all pages into one tall image, e.g. to post a whole document at once.`,
    `Il preset Immagine lunga impila tutte le pagine in un'unica immagine alta, per esempio per pubblicare un documento intero in una volta.`],
  [`compress PDF`, `comprimi PDF`],
  [`The Compress PDF preset makes a PDF smaller while it stays a PDF: pictures are scaled down to 72, 150 or 300 dpi and photos saved again as JPEG, while text, fonts, links, bookmarks and forms stay. A PDF that can't get smaller is left as it was. With Ghostscript installed, Filee can try it too and keep the smaller result.`,
    `Il preset Comprimi PDF rende un PDF più piccolo lasciandolo un PDF: le immagini vengono ridotte a 72, 150 o 300 dpi e le foto salvate di nuovo come JPEG, mentre testo, font, link, segnalibri e moduli restano. Un PDF che non può diventare più piccolo resta com'era. Con Ghostscript installato, Filee può provare anche con quello e tenere il risultato più piccolo.`],
  [`a picture per slide`, `un'immagine per slide`],
  [`PPTX (slides) puts a picture of each page on its own slide, at the page's size, with the page's text in the speaker notes. The slides look exactly like the PDF but aren't editable; convert to DOCX for editable text.`,
    `PPTX (slide) mette un'immagine di ogni pagina su una slide a sé, alle dimensioni della pagina, con il testo della pagina nelle note del relatore. Le slide sono identiche al PDF ma non sono modificabili; converti in DOCX per avere testo modificabile.`],
  [`vector PDF`, `PDF vettoriale`],
  [`The PDF stays vector, so it is sharp at any zoom and in print.`,
    `Il PDF resta vettoriale, quindi è nitido a qualsiasi zoom e in stampa.`],
  [`editable`, `modificabile`],
  [`The result has real text and paragraphs you can edit, not pictures of pages.`,
    `Il risultato ha testo e paragrafi veri che puoi modificare, non immagini delle pagine.`],
  [`attachments as ZIP`, `allegati come ZIP`],
  [`Attachments can be saved separately as one ZIP.`, `Gli allegati si possono salvare a parte in un unico ZIP.`],
  [`one CSV per sheet`, `un CSV per foglio`],
  [`Workbooks with several sheets give one CSV per sheet.`,
    `Le cartelle di lavoro con più fogli danno un CSV per foglio.`],
  [`layout kept`, `impaginazione mantenuta`],
  [`Keeps page size and margins, headers and footers with page numbers, tables, text boxes, shapes and pictures.`,
    `Mantiene dimensioni e margini della pagina, intestazioni e piè di pagina con i numeri di pagina, tabelle, caselle di testo, forme e immagini.`],
  [`no Office needed`, `Office non serve`],
  [`No Microsoft Office or LibreOffice needed.`, `Non servono Microsoft Office né LibreOffice.`],
  [`no Hancom Office needed`, `Hancom Office non serve`],
  [`No Hancom Office and no approval dialog.`, `Niente Hancom Office e nessuna finestra di autorizzazione.`],
  [`no AutoCAD needed`, `AutoCAD non serve`],
  [`No AutoCAD or DWG viewer needed.`, `Non servono AutoCAD né un visualizzatore DWG.`],
  [`no re-encoding`, `nessuna ricodifica`],
  [`When the new format can hold the video and sound as they are (an iPhone MOV → MP4), they are only rewrapped: no quality lost, HDR kept, done in seconds.`,
    `Quando il nuovo formato può contenere video e audio così come sono (un MOV di iPhone → MP4), vengono solo reimpacchettati: nessuna perdita di qualità, HDR mantenuto, fatto in pochi secondi.`],
  [`720p option`, `opzione 720p`],
  [`The MP4 720p preset shrinks large videos for sharing.`,
    `Il preset MP4 720p riduce i video grandi per condividerli.`],
  [`extract audio`, `estrai audio`],
  [`Only the sound is saved, without the video track.`, `Viene salvato solo l'audio, senza la traccia video.`],
  [`MP3 128k`, `MP3 128k`],
  [`The MP3 128k preset makes smaller files, ideal for speech.`,
    `Il preset MP3 128k crea file più piccoli, ideali per il parlato.`],
  [`extract`, `estrai`],
  [`The extract preset unpacks an archive into a folder instead.`,
    `Il preset Estrai invece scompatta un archivio in una cartella.`],
  [`pack into one ZIP`, `un unico ZIP`],
  [`Any selection of files can be packed into one ZIP.`,
    `Qualsiasi selezione di file si può mettere in un unico ZIP.`],
  [`DRM-free books`, `libri senza DRM`],
  [`Works with DRM-free books only.`, `Funziona solo con libri senza DRM.`],
  [`ALAC in M4A`, `ALAC in M4A`],
  [`M4A can hold lossless ALAC as well as AAC.`, `M4A può contenere ALAC senza perdita oltre ad AAC.`],
  [`HEVC / AV1`, `HEVC / AV1`],
  [`Video presets can encode HEVC (H.265) or AV1 for smaller files, keeping 10-bit and HDR video.`,
    `I preset video possono codificare in HEVC (H.265) o AV1 per file più piccoli, mantenendo i video a 10 bit e HDR.`],
  [`hardware encoding`, `codifica hardware`],
  [`Turn on Use hardware acceleration in a video preset to encode H.264 and HEVC on the graphics chip (NVENC, Quick Sync, AMF, VideoToolbox or VA-API): much faster and lighter on power, slightly larger at the same quality. It is off by default, and without a usable chip the video is encoded as before.`,
    `Attiva Usa l'accelerazione hardware in un preset video per codificare H.264 e HEVC sul chip grafico (NVENC, Quick Sync, AMF, VideoToolbox o VA-API): molto più veloce e con meno consumi, file leggermente più grandi a parità di qualità. È disattivata per impostazione predefinita e, senza un chip utilizzabile, il video viene codificato come prima.`],
  [`every frame`, `ogni fotogramma`],
  [`Usually a video gives one still frame. The Extract frames presets, or Save every frame of a video in a PNG or JPG preset, save every frame (or every Nth) as pictures in a folder next to the video.`,
    `Di solito un video dà un solo fotogramma. I preset Estrai fotogrammi, o Salva ogni fotogramma di un video in un preset PNG o JPG, salvano ogni fotogramma (o uno ogni N) come immagini in una cartella accanto al video.`],
  [`extract subtitles`, `estrai sottotitoli`],
  [`The Extract subtitles preset on the video donut saves the first text subtitle track of a video as SRT.`,
    `Il preset Estrai sottotitoli del donut dei video salva in SRT la prima traccia di sottotitoli testuali di un video.`],
  [`saved as UTF-8`, `salvato in UTF-8`],
  [`Results are saved as UTF-8. Korean files saved in CP949 (EUC-KR) are detected and read correctly.`,
    `I risultati vengono salvati in UTF-8. I file coreani salvati in CP949 (EUC-KR) vengono riconosciuti e letti correttamente.`],
  [`tables to CSV / Excel`, `tabelle in CSV / Excel`],
  [`Data that is a table (a list of records) also converts to and from CSV and Excel.`,
    `I dati che sono una tabella (un elenco di record) si convertono anche da e verso CSV ed Excel.`],
  [`picture preview`, `anteprima come immagine`],
  [`PNG or JPG gives a shaded picture of the model, seen from the front right and above.`,
    `PNG o JPG danno un'immagine ombreggiata del modello, vista da davanti a destra e dall'alto.`],
  [`colours and textures`, `colori e texture`],
  [`Colours, textures and materials are kept where the target format can hold them. STL keeps only the shape.`,
    `Colori, texture e materiali vengono mantenuti dove il formato di destinazione li supporta. STL mantiene solo la forma.`],
  [`HDR tone-mapped`, `HDR con tone mapping`],
  [`HDR screenshots that Windows saves as JPEG XR are tone-mapped to normal brightness instead of being clipped.`,
    `Gli screenshot HDR che Windows salva come JPEG XR vengono riportati a una luminosità normale con il tone mapping invece di essere tagliati.`],
  [`Live Photo video`, `video della Live Photo`],
  [`The Extract Live Photo video preset saves the video of an iPhone Live Photo (a LIVP from iCloud, or a photo with its MOV) or an Android Motion Photo as MP4 or MOV. The other way round, the Live Photo (iPhone) and Motion Photo (Android) presets turn a short clip of a video into a moving photo; that is still experimental.`,
    `Il preset Estrai il video della Live Photo salva il video di una Live Photo di iPhone (un LIVP da iCloud, o una foto con il suo MOV) o di una Motion Photo di Android come MP4 o MOV. Al contrario, i preset Live Photo (iPhone) e Motion Photo (Android) trasformano un breve spezzone di un video in una foto in movimento; questo è ancora sperimentale.`],
  [`WGS 84 longitude / latitude`, `longitudine / latitudine WGS 84`],
  [`Results are always in longitude and latitude (WGS 84). Shapefiles in UTM, Web Mercator, Lambert or Albers are converted, so they open in the right place; converting a file to its own format reprojects it.`,
    `I risultati sono sempre in longitudine e latitudine (WGS 84). Gli Shapefile in UTM, Web Mercator, Lambert o Albers vengono convertiti, così si aprono nel punto giusto; convertire un file nel suo stesso formato lo riproietta.`],
  [`save as ZIP`, `salva come ZIP`],
  [`A Shapefile is five files (.shp, .shx, .dbf, .prj and .cpg). With Save the result as a ZIP in a preset, or for every geospatial result in the settings, they travel together in one ZIP.`,
    `Uno Shapefile è composto da cinque file (.shp, .shx, .dbf, .prj e .cpg). Con Salva il risultato come ZIP in un preset, o per ogni risultato geospaziale nelle impostazioni, viaggiano insieme in un unico ZIP.`],
  [`Canon CR2 RAW photo`, `Foto RAW Canon CR2`],
  [`CR2 is the RAW photo format Canon DSLRs used for many years (newer Canon models write CR3). It stores the unprocessed sensor data, which leaves plenty of room for editing.`,
    `CR2 è il formato RAW che le reflex Canon hanno usato per molti anni (i modelli Canon più recenti scrivono CR3). Contiene i dati del sensore non elaborati, che lasciano molto margine per la modifica.`],
  [`Nikon NEF RAW photo`, `Foto RAW Nikon NEF`],
  [`NEF is Nikon's RAW photo format, used by Nikon DSLRs and Z mirrorless cameras. Like other RAW files it holds unprocessed sensor data and is several times larger than a JPG.`,
    `NEF è il formato RAW di Nikon, usato dalle reflex Nikon e dalle mirrorless Z. Come altri file RAW contiene i dati del sensore non elaborati ed è parecchie volte più grande di un JPG.`],

  // Text that needs shaping
  [`DOCX, TXT, Markdown, HTML, XLSX, PPTX and HWPX with text that needs shaping (Arabic, Hebrew, Indic scripts, Thai and others) go to PDF and images through the optional LibreOffice engine`,
    `DOCX, TXT, Markdown, HTML, XLSX, PPTX e HWPX con testo che richiede lo shaping dei glifi (arabo, ebraico, scritture indiane, thai e altre) passano a PDF e immagini con il motore facoltativo LibreOffice`],
  [`Text that needs shaping (Arabic, Hebrew, Indic scripts, Thai and others) is the exception: DOCX, TXT, Markdown, HTML, XLSX, PPTX and HWPX files with it go to PDF and images through the optional LibreOffice engine. Without LibreOffice, that file fails with a message naming the script instead of becoming a broken PDF.`,
    `Fa eccezione il testo che richiede lo shaping dei glifi (arabo, ebraico, scritture indiane, thai e altre): i file DOCX, TXT, Markdown, HTML, XLSX, PPTX e HWPX che lo contengono passano a PDF e immagini con il motore facoltativo LibreOffice. Senza LibreOffice la conversione di quel file non riesce e un messaggio indica la scrittura, invece di produrre un PDF difettoso.`],

  // Images
  [`Images`, `Immagini`],
  [`images`, `immagini`],
  [`Photos and graphics, including iPhone HEIC and Live Photos, Photoshop PSD, camera RAW from all major brands, animated APNG, DICOM and the HDR screenshots of Windows (JPEG XR). Resize, rotate, set quality and DPI or strip metadata while converting, or trace a picture into an SVG.`,
    `Foto e grafica, compresi HEIC e Live Photo di iPhone, PSD di Photoshop, RAW delle fotocamere di tutte le principali marche, APNG animati, DICOM e gli screenshot HDR di Windows (JPEG XR). Ridimensiona, ruota, imposta qualità e DPI o rimuovi i metadati durante la conversione, oppure trasforma un'immagine in un SVG.`],
  [`JPEG image`, `Immagine JPEG`],
  [`JPEG is the most widely used photo format. Its lossy compression keeps files small, but every save at lower quality discards some detail, and it has no transparency.`,
    `JPEG è il formato fotografico più diffuso. La sua compressione con perdita mantiene i file piccoli, ma ogni salvataggio a qualità più bassa scarta qualche dettaglio, e non ha trasparenza.`],
  [`PNG image`, `Immagine PNG`],
  [`PNG is a lossless image format with transparency, ideal for screenshots, logos and graphics with sharp edges. Photos saved as PNG are usually much larger than JPG.`,
    `PNG è un formato di immagine senza perdita con trasparenza, ideale per screenshot, loghi e grafica con bordi netti. Le foto salvate in PNG sono di solito molto più grandi che in JPG.`],
  [`WebP image`, `Immagine WebP`],
  [`WebP is Google's image format for the web. It supports lossy and lossless compression and transparency and is usually smaller than JPG or PNG, but some editors and upload forms still don't accept it.`,
    `WebP è il formato di immagine di Google per il web. Supporta la compressione con e senza perdita e la trasparenza ed è di solito più piccolo di JPG o PNG, ma alcuni editor e moduli di caricamento non lo accettano ancora.`],
  [`AVIF image`, `Immagine AVIF`],
  [`AVIF is a modern image format based on the AV1 video codec. It compresses better than JPG and WebP, but support in older software and devices is still limited.`,
    `AVIF è un formato di immagine moderno basato sul codec video AV1. Comprime meglio di JPG e WebP, ma il supporto nei software e nei dispositivi più vecchi è ancora limitato.`],
  [`HEIC / HEIF image`, `Immagine HEIC / HEIF`],
  [`HEIC (HEIF) is the photo format iPhones and iPads use by default. Photos are often about half the size of a JPG, but many Windows apps, websites and older devices can't open them.`,
    `HEIC (HEIF) è il formato fotografico che iPhone e iPad usano per impostazione predefinita. Le foto sono spesso grandi circa la metà di un JPG, ma molte app di Windows, siti web e dispositivi più vecchi non riescono ad aprirle.`],
  [`GIF image / animation`, `Immagine / animazione GIF`],
  [`GIF is an old image format limited to 256 colours that supports simple animation. It is still the universal way to share short silent loops in chats, documents and bug reports.`,
    `GIF è un vecchio formato di immagine limitato a 256 colori che supporta animazioni semplici. È ancora il modo universale per condividere brevi loop senza audio in chat, documenti e segnalazioni di bug.`],
  [`Windows icon`, `Icona di Windows`],
  [`ICO is the Windows icon format. One ICO file holds the same picture at several sizes (for example 16, 32, 48 and 256 pixels), so it looks sharp everywhere from the taskbar to website favicons.`,
    `ICO è il formato delle icone di Windows. Un file ICO contiene la stessa immagine in più dimensioni (per esempio 16, 32, 48 e 256 pixel), così appare nitida ovunque, dalla barra delle applicazioni alle favicon dei siti web.`],
  [`Photoshop document`, `Documento Photoshop`],
  [`PSD is Adobe Photoshop's native format. It keeps layers, masks and adjustment settings, so it is great for editing but can't be opened by most viewers or websites.`,
    `PSD è il formato nativo di Adobe Photoshop. Mantiene livelli, maschere e regolazioni, quindi è ottimo per la modifica ma la maggior parte dei visualizzatori e dei siti web non riesce ad aprirlo.`],
  [`macOS icon`, `Icona di macOS`],
  [`ICNS is the icon format of macOS. Like ICO it bundles several sizes of one image, up to 1024×1024 for Retina displays, and is used for app icons on the Mac.`,
    `ICNS è il formato delle icone di macOS. Come ICO raccoglie più dimensioni di un'immagine, fino a 1024×1024 per i display Retina, e si usa per le icone delle app sul Mac.`],
  [`Camera RAW`, `RAW della fotocamera`],
  [`Windows only`, `solo Windows`],
  [`the photo of the Live Photo`, `la foto della Live Photo`],
  [`the video of the Live Photo`, `il video della Live Photo`],

  // Vector graphics
  [`Vector graphics`, `Grafica vettoriale`],
  [`vector graphics`, `grafica vettoriale`],
  [`SVG, Windows metafiles, Illustrator, EPS/PostScript and drawings from CorelDRAW, Visio and LibreOffice Draw. SVG also becomes DXF or DWG for CAD.`,
    `SVG, metafile di Windows, Illustrator, EPS/PostScript e disegni di CorelDRAW, Visio e LibreOffice Draw. SVG diventa anche DXF o DWG per il CAD.`],
  [`SVG vector graphic`, `Grafica vettoriale SVG`],
  [`SVG is an XML-based vector graphics format. Shapes and text stay sharp at any size, which makes it ideal for logos and icons on the web, but many apps and upload forms only accept pixel images.`,
    `SVG è un formato di grafica vettoriale basato su XML. Forme e testo restano nitidi a qualsiasi dimensione, il che lo rende ideale per loghi e icone sul web, ma molte app e molti moduli di caricamento accettano solo immagini a pixel.`],
  [`Encapsulated PostScript`, `Encapsulated PostScript`],
  [`EPS is a vector format from print and design work, often used for logos and illustrations sent to print shops. Most modern apps can't show it without a PostScript interpreter.`,
    `EPS è un formato vettoriale del mondo della stampa e della grafica, usato spesso per loghi e illustrazioni da inviare in tipografia. La maggior parte delle app moderne non riesce a mostrarlo senza un interprete PostScript.`],
  [`AI files saved with PDF content (Illustrator's default)`, `file AI salvati con contenuto PDF (l'impostazione predefinita di Illustrator)`],

  // PDF
  [`PDF`, `PDF`],
  [`Turn PDFs into images, editable Word or HWPX documents, PowerPoint slides, text or a comic archive, and merge, split, compress or pick pages.`,
    `Trasforma i PDF in immagini, documenti Word o HWPX modificabili, slide di PowerPoint, testo o un archivio di fumetti, e unisci, dividi, comprimi o scegli le pagine.`],
  [`PDF document`, `Documento PDF`],
  [`PDF is the standard for sharing documents that must look the same everywhere. Fonts, layout and images are fixed, and it opens on any device. That also makes PDFs hard to edit.`,
    `PDF è lo standard per condividere documenti che devono apparire uguali ovunque. Font, impaginazione e immagini sono fissi e si apre su qualsiasi dispositivo. Proprio per questo i PDF sono difficili da modificare.`],
  [`one page`, `una pagina`],

  // Documents
  [`Documents`, `Documenti`],
  [`documents`, `documenti`],
  [`Word documents without Microsoft Office, Chinese OFD e-invoices, older and rare word-processor formats with the optional LibreOffice engine, and saved e-mails (EML and Outlook MSG).`,
    `Documenti Word senza Microsoft Office, fatture elettroniche cinesi OFD, formati di videoscrittura più vecchi e rari con il motore facoltativo LibreOffice, ed e-mail salvate (EML e MSG di Outlook).`],
  [`Word document`, `Documento Word`],
  [`DOCX is the Microsoft Word format since Word 2007 (Office Open XML). It is the most common format for editable documents such as reports, letters and forms.`,
    `DOCX è il formato di Microsoft Word da Word 2007 (Office Open XML). È il formato più comune per i documenti modificabili come relazioni, lettere e moduli.`],
  [`Word 97–2003 document`, `Documento Word 97–2003`],
  [`DOC is the binary format of Word 97–2003. Old archives, official forms and legacy systems still produce it, but it is being replaced by DOCX.`,
    `DOC è il formato binario di Word 97–2003. Vecchi archivi, moduli ufficiali e sistemi datati lo producono ancora, ma viene sostituito da DOCX.`],
  [`E-mail message`, `Messaggio e-mail`],
  [`EML is a single e-mail saved as a file (MIME format), with the headers, the message and its attachments. Most mail apps, including Outlook and Thunderbird, can open it.`,
    `EML è una singola e-mail salvata come file (formato MIME), con le intestazioni, il messaggio e i suoi allegati. La maggior parte delle app di posta, compresi Outlook e Thunderbird, riesce ad aprirlo.`],
  [`Outlook message`, `Messaggio di Outlook`],
  [`MSG is the file Microsoft Outlook saves when you drag an e-mail out of it. Only Outlook opens it, so it is hard to read on a PC without Outlook or on a phone.`,
    `MSG è il file che Microsoft Outlook salva quando trascini fuori un'e-mail. Lo apre solo Outlook, quindi è difficile da leggere su un PC senza Outlook o su un telefono.`],

  // HWP
  [`HWP (Hangul)`, `HWP (Hangul)`],
  [`Korean HWP/HWPX`, `HWP/HWPX coreani`],
  [`Korean Hancom Hangul documents without Hancom Office: HWP ↔ HWPX, to PDF, images, Word, text, Markdown and HTML, and HWPX from Word, Excel, PowerPoint, Markdown and PDF.`,
    `Documenti coreani di Hancom Hangul senza Hancom Office: HWP ↔ HWPX, in PDF, immagini, Word, testo, Markdown e HTML, e HWPX da Word, Excel, PowerPoint, Markdown e PDF.`],
  [`Hangul document (HWP)`, `Documento Hangul (HWP)`],
  [`HWP is the document format of Hancom Office Hangul (한글), the standard word processor in Korean government offices, schools and many companies. Outside Korea few programs can open it.`,
    `HWP è il formato dei documenti di Hancom Office Hangul (한글), il programma di videoscrittura standard negli uffici pubblici, nelle scuole e in molte aziende della Corea. Fuori dalla Corea pochi programmi riescono ad aprirlo.`],
  [`Hangul document (HWPX)`, `Documento Hangul (HWPX)`],
  [`HWPX is the open, XML-based format of Hancom Hangul (OWPML, Korean national standard KS X 6101). Korean public institutions are moving to it from the binary HWP format.`,
    `HWPX è il formato aperto basato su XML di Hancom Hangul (OWPML, standard nazionale coreano KS X 6101). Gli enti pubblici coreani lo stanno adottando al posto del formato binario HWP.`],

  // Spreadsheets
  [`Spreadsheets`, `Fogli di calcolo`],
  [`spreadsheets`, `fogli di calcolo`],
  [`Excel, OpenDocument and CSV/TSV sheets, to PDF with Excel-like page fitting or into each other, without Excel.`,
    `Fogli Excel, OpenDocument e CSV/TSV, in PDF con l'adattamento alla pagina come in Excel o tra loro, senza Excel.`],
  [`Excel workbook`, `Cartella di lavoro Excel`],
  [`XLSX is the Microsoft Excel workbook format since Excel 2007. One workbook can hold several sheets with formulas, formatting, charts and pictures.`,
    `XLSX è il formato delle cartelle di lavoro di Microsoft Excel da Excel 2007. Una cartella di lavoro può contenere più fogli con formule, formattazione, grafici e immagini.`],
  [`Excel 97–2003 workbook`, `Cartella di lavoro Excel 97–2003`],
  [`XLS is the binary workbook format of Excel 97–2003. Many older systems and bank or accounting exports still produce it.`,
    `XLS è il formato binario delle cartelle di lavoro di Excel 97–2003. Molti sistemi più vecchi e le esportazioni di banche o contabilità lo producono ancora.`],
  [`Comma-separated values`, `Valori separati da virgole`],
  [`CSV is plain text with one table row per line. Every spreadsheet, database and programming language reads it, but it has no formatting, formulas or multiple sheets.`,
    `CSV è testo semplice con una riga di tabella per riga. Qualsiasi foglio di calcolo, database e linguaggio di programmazione lo legge, ma non ha formattazione, formule né più fogli.`],

  // Presentations
  [`Presentations`, `Presentazioni`],
  [`presentations`, `presentazioni`],
  [`PowerPoint to PDF, images and HWPX without PowerPoint; older PPT, ODP and Keynote with the optional LibreOffice engine.`,
    `PowerPoint in PDF, immagini e HWPX senza PowerPoint; PPT più vecchi, ODP e Keynote con il motore facoltativo LibreOffice.`],
  [`PowerPoint presentation`, `Presentazione PowerPoint`],
  [`PPTX is the Microsoft PowerPoint format since PowerPoint 2007. It holds slides with text, pictures, shapes, tables, notes and animations.`,
    `PPTX è il formato di Microsoft PowerPoint da PowerPoint 2007. Contiene slide con testo, immagini, forme, tabelle, note e animazioni.`],
  [`PowerPoint 97–2003 presentation`, `Presentazione PowerPoint 97–2003`],
  [`PPT is the binary format of PowerPoint 97–2003. Old lecture slides and archived presentations are often still in PPT.`,
    `PPT è il formato binario di PowerPoint 97–2003. Le vecchie slide delle lezioni e le presentazioni archiviate sono spesso ancora in PPT.`],

  // Text & markup
  [`Text & markup`, `Testo e markup`],
  [`text and markup`, `testo e markup`],
  [`Plain text, Markdown, HTML and saved web pages (MHTML) to PDF, Word, HWPX and EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter and other markup use the optional Pandoc engine, which also turns Markdown into PowerPoint slides.`,
    `Testo semplice, Markdown, HTML e pagine web salvate (MHTML) in PDF, Word, HWPX ed EPUB. LaTeX, reStructuredText, Org, AsciiDoc, Typst, Jupyter e altri linguaggi di markup usano il motore facoltativo Pandoc, che trasforma anche il Markdown in slide di PowerPoint.`],
  [`Plain text`, `Testo semplice`],
  [`TXT is plain text without any formatting, the simplest and most portable document format. The only thing that can differ is the character encoding (UTF-8, UTF-16 or a legacy code page).`,
    `TXT è testo semplice senza alcuna formattazione, il formato di documento più semplice e portabile. L'unica cosa che può cambiare è la codifica dei caratteri (UTF-8, UTF-16 o una vecchia tabella codici).`],
  [`Markdown`, `Markdown`],
  [`Markdown is a lightweight plain-text markup: # for headings, * for lists, ** for bold. It is popular for notes, README files and documentation, and is readable even without rendering.`,
    `Markdown è un linguaggio di markup leggero in testo semplice: # per i titoli, * per gli elenchi, ** per il grassetto. È molto usato per note, file README e documentazione, ed è leggibile anche senza rendering.`],
  [`Web page (HTML)`, `Pagina web (HTML)`],
  [`HTML is the language of web pages. A saved .html file opens in any browser, but how it looks depends on the browser and on linked styles and images, which may be missing offline.`,
    `HTML è il linguaggio delle pagine web. Un file .html salvato si apre in qualsiasi browser, ma il suo aspetto dipende dal browser e dagli stili e dalle immagini collegati, che offline possono mancare.`],
  [`LOG files and scripts (PY, PAC, BAT, COMMAND) are read as text and never run`,
    `i file LOG e gli script (PY, PAC, BAT, COMMAND) vengono letti come testo e mai eseguiti`],
  [`the saved page, with its pictures`, `la pagina salvata, con le sue immagini`],

  // Data
  [`Data`, `Dati`],
  [`data files`, `file di dati`],
  [`JSON, JSON Lines, YAML, TOML and XML into each other, and tables to and from CSV and Excel. vCard contacts to and from CSV, also from old phones. Nothing to install.`,
    `JSON, JSON Lines, YAML, TOML e XML tra loro, e tabelle da e verso CSV ed Excel. Contatti vCard da e verso CSV, anche da vecchi telefoni. Niente da installare.`],
  [`JSON data`, `Dati JSON`],
  [`JSON is the data format of the web: objects, lists, text and numbers in plain text. APIs, apps and settings files use it everywhere.`,
    `JSON è il formato di dati del web: oggetti, elenchi, testo e numeri in testo semplice. API, app e file di impostazioni lo usano ovunque.`],
  [`YAML data`, `Dati YAML`],
  [`YAML holds the same kind of data as JSON, written with indentation instead of brackets. Config files for Docker, Kubernetes, CI pipelines and many apps are YAML.`,
    `YAML contiene lo stesso tipo di dati di JSON, scritto con il rientro invece delle parentesi. I file di configurazione di Docker, Kubernetes, delle pipeline CI e di molte app sono in YAML.`],
  [`vCard contacts`, `Contatti vCard`],
  [`vCard (.vcf) is the standard file for contacts. Phones, Outlook, Google Contacts and iCloud export address books as vCard, often many contacts in one file.`,
    `vCard (.vcf) è il file standard per i contatti. Telefoni, Outlook, Google Contatti e iCloud esportano le rubriche in vCard, spesso con molti contatti in un unico file.`],

  // E-books
  [`E-books & comics`, `E-book e fumetti`],
  [`e-books and comics`, `e-book e fumetti`],
  [`EPUB, Kindle (MOBI, AZW, AZW3), FictionBook and comic archives (CBZ, CBR, CB7…) to PDF, EPUB, Word and more, and KEPUB for Kobo readers. DRM-free books only.`,
    `EPUB, Kindle (MOBI, AZW, AZW3), FictionBook e archivi di fumetti (CBZ, CBR, CB7…) in PDF, EPUB, Word e altro, e KEPUB per i lettori Kobo. Solo libri senza DRM.`],
  [`EPUB e-book`, `E-book EPUB`],
  [`EPUB is the open standard for e-books. Text reflows to fit any screen, and most e-readers and reading apps support it; Kindle accepts EPUB through Send to Kindle.`,
    `EPUB è lo standard aperto per gli e-book. Il testo si adatta a qualsiasi schermo e la maggior parte degli e-reader e delle app di lettura lo supporta; Kindle accetta EPUB tramite Send to Kindle.`],
  [`Kindle / Mobipocket e-book`, `E-book Kindle / Mobipocket`],
  [`MOBI is the older Mobipocket e-book format that Amazon Kindle used for years. It is still common in older e-book collections, but Amazon has moved to AZW3/KFX and EPUB.`,
    `MOBI è il vecchio formato di e-book Mobipocket che Amazon Kindle ha usato per anni. È ancora comune nelle raccolte di e-book più vecchie, ma Amazon è passata ad AZW3/KFX ed EPUB.`],

  // Video
  [`Video`, `Video`],
  [`video`, `video`],
  [`All common video formats to MP4 (H.264, HEVC or AV1), WebM, MOV, MKV, AVI, GIF or APNG, with a 720p option, hardware encoding on the graphics chip, audio extraction to MP3 or M4A and every frame saved as pictures. Uses the optional FFmpeg engine.`,
    `Tutti i formati video comuni in MP4 (H.264, HEVC o AV1), WebM, MOV, MKV, AVI, GIF o APNG, con un'opzione 720p, la codifica hardware sul chip grafico, l'estrazione dell'audio in MP3 o M4A e ogni fotogramma salvato come immagine. Usa il motore facoltativo FFmpeg.`],
  [`MPEG-4 video`, `Video MPEG-4`],
  [`MP4 (MPEG-4 Part 14) is the most compatible video format. It plays on phones, TVs, browsers and every video site, usually with H.264 or H.265 video and AAC audio.`,
    `MP4 (MPEG-4 Part 14) è il formato video più compatibile. Si riproduce su telefoni, TV, browser e su ogni sito di video, di solito con video H.264 o H.265 e audio AAC.`],
  [`QuickTime movie`, `Filmato QuickTime`],
  [`MOV is Apple's QuickTime video format, used by iPhones and Macs. It usually contains H.264 or HEVC video, but some editors, TVs and websites handle MP4 better.`,
    `MOV è il formato video QuickTime di Apple, usato da iPhone e Mac. Di solito contiene video H.264 o HEVC, ma alcuni editor, TV e siti web gestiscono meglio MP4.`],
  [`Matroska video`, `Video Matroska`],
  [`MKV (Matroska) is a flexible open container that can hold many video, audio and subtitle tracks. It is popular for films and recordings, but phones, TVs and editors don't always play it.`,
    `MKV (Matroska) è un contenitore aperto e flessibile che può contenere molte tracce video, audio e di sottotitoli. È molto usato per film e registrazioni, ma telefoni, TV ed editor non sempre lo riproducono.`],
  [`WebM video`, `Video WebM`],
  [`WebM is an open video format made for browsers (VP8/VP9 or AV1 video with Vorbis or Opus audio). Screen recordings and downloads are often WebM, but many editors and devices expect MP4.`,
    `WebM è un formato video aperto pensato per i browser (video VP8/VP9 o AV1 con audio Vorbis o Opus). Le registrazioni dello schermo e i download sono spesso in WebM, ma molti editor e dispositivi si aspettano MP4.`],
  [`AVI video`, `Video AVI`],
  [`AVI is Microsoft's video container from the 1990s. Camcorders, older cameras and archives still hold AVI files, which are often large and poorly supported on phones.`,
    `AVI è il contenitore video di Microsoft degli anni '90. Videocamere, fotocamere più vecchie e archivi contengono ancora file AVI, spesso grandi e poco supportati sui telefoni.`],
  [`one still frame or every frame`, `un fotogramma o ogni fotogramma`],

  // Audio
  [`Audio`, `Audio`],
  [`audio`, `audio`],
  [`Music, recordings and voice memos to MP3, M4A, WAV, FLAC, OGG, Opus, AAC or lossless WavPack and TTA. APE, DSD and DTS are read too. Uses the optional FFmpeg engine.`,
    `Musica, registrazioni e memo vocali in MP3, M4A, WAV, FLAC, OGG, Opus, AAC o WavPack e TTA senza perdita. Si leggono anche APE, DSD e DTS. Usa il motore facoltativo FFmpeg.`],
  [`MP3 audio`, `Audio MP3`],
  [`MP3 is the classic compressed audio format. Practically every player, car stereo and phone plays it, which makes it the safest choice for sharing music, podcasts and recordings.`,
    `MP3 è il classico formato audio compresso. Lo riproducono praticamente tutti i lettori, le autoradio e i telefoni, il che lo rende la scelta più sicura per condividere musica, podcast e registrazioni.`],
  [`MPEG-4 audio`, `Audio MPEG-4`],
  [`M4A is an MPEG-4 audio file, usually AAC, used by iTunes, iPhone voice memos and many recorders. It sounds good at small sizes, but some players and car stereos only take MP3.`,
    `M4A è un file audio MPEG-4, di solito AAC, usato da iTunes, dai memo vocali di iPhone e da molti registratori. Suona bene con file piccoli, ma alcuni lettori e autoradio accettano solo MP3.`],
  [`WAV audio`, `Audio WAV`],
  [`WAV is uncompressed audio (usually PCM) used for recording and editing. It sounds exactly like the source but takes about 10 MB per minute in CD quality.`,
    `WAV è audio non compresso (di solito PCM) usato per registrare e montare. Suona esattamente come l'originale ma occupa circa 10 MB al minuto in qualità CD.`],
  [`FLAC lossless audio`, `Audio FLAC senza perdita`],
  [`FLAC is lossless compressed audio: it shrinks files to roughly half the size of WAV without losing any quality, which makes it the favourite format for music libraries and hi-res downloads.`,
    `FLAC è audio compresso senza perdita: riduce i file a circa la metà di un WAV senza perdere qualità, il che lo rende il formato preferito per le librerie musicali e i download ad alta risoluzione.`],

  // Subtitles
  [`Subtitles`, `Sottotitoli`],
  [`subtitles`, `sottotitoli`],
  [`SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML and MicroDVD into each other without any engine, saved as UTF-8; SSA and SCC are read. Korean SMI and SRT files in CP949 are read correctly. Subtitles in a video come out with FFmpeg.`,
    `SRT, ASS, WebVTT, SAMI (SMI), LRC, TTML e MicroDVD tra loro senza alcun motore, salvati in UTF-8; si leggono anche SSA e SCC. I file SMI e SRT coreani in CP949 vengono letti correttamente. I sottotitoli contenuti in un video si estraggono con FFmpeg.`],
  [`SubRip subtitles`, `Sottotitoli SubRip`],
  [`SRT (SubRip) is the most common subtitle file: numbered cues with start and end times and plain text. Nearly every player, editor and video site accepts it.`,
    `SRT (SubRip) è il file di sottotitoli più comune: battute numerate con orari di inizio e fine e testo semplice. Quasi ogni lettore, editor e sito di video lo accetta.`],
  [`Advanced SubStation Alpha subtitles`, `Sottotitoli Advanced SubStation Alpha`],
  [`ASS (Advanced SubStation Alpha) is the styled subtitle format of anime fansubs and Aegisub, with fonts, colours, positions and effects. Many devices and sites only take plain SRT.`,
    `ASS (Advanced SubStation Alpha) è il formato di sottotitoli con stili dei fansub di anime e di Aegisub, con font, colori, posizioni ed effetti. Molti dispositivi e siti accettano solo SRT semplici.`],
  [`WebVTT subtitles`, `Sottotitoli WebVTT`],
  [`WebVTT (.vtt) is the subtitle format of HTML5 video. Web players, YouTube and online course platforms use it.`,
    `WebVTT (.vtt) è il formato di sottotitoli dei video HTML5. Lo usano i lettori web, YouTube e le piattaforme di corsi online.`],
  [`SAMI subtitles (SMI)`, `Sottotitoli SAMI (SMI)`],
  [`SAMI (.smi) is Microsoft's HTML-like subtitle format. It is still the classic subtitle file in Korea, often saved in the old CP949 encoding that newer players show as broken text.`,
    `SAMI (.smi) è il formato di sottotitoli di Microsoft simile all'HTML. In Corea è ancora il classico file di sottotitoli, spesso salvato nella vecchia codifica CP949 che i lettori più recenti mostrano come testo illeggibile.`],

  // Archives
  [`Archives`, `Archivi`],
  [`archives`, `archivi`],
  [`Repack or extract ZIP, 7Z, RAR, TAR, disk images and many more archive formats with the bundled 7-Zip engine, or pack any files into one ZIP.`,
    `Ricomprimi o estrai ZIP, 7Z, RAR, TAR, immagini disco e molti altri formati di archivio con il motore 7-Zip incluso, oppure metti qualsiasi file in un unico ZIP.`],
  [`ZIP archive`, `Archivio ZIP`],
  [`ZIP is the universal archive format. Windows, macOS, phones and nearly every upload form open it without extra software.`,
    `ZIP è il formato di archivio universale. Windows, macOS, i telefoni e quasi ogni modulo di caricamento lo aprono senza software aggiuntivo.`],
  [`7-Zip archive`, `Archivio 7-Zip`],
  [`7Z is the open archive format of 7-Zip. Its LZMA2 compression usually makes smaller files than ZIP, but not every system or website can open it.`,
    `7Z è il formato di archivio aperto di 7-Zip. La sua compressione LZMA2 di solito crea file più piccoli di ZIP, ma non tutti i sistemi e i siti web riescono ad aprirlo.`],
  [`RAR archive`, `Archivio RAR`],
  [`RAR is the proprietary archive format of WinRAR, common for downloads split into parts. Recent Windows 11 versions can open RAR but can't create it, and many tools only accept ZIP.`,
    `RAR è il formato di archivio proprietario di WinRAR, comune per i download divisi in parti. Le versioni recenti di Windows 11 aprono i RAR ma non li creano, e molti strumenti accettano solo ZIP.`],
  [`Any files`, `Qualsiasi file`],

  // CAD
  [`CAD drawings`, `Disegni CAD`],
  [`CAD drawings [in running text]`, `disegni CAD`],
  [`AutoCAD DWG and DXF: convert between them or to PDF, SVG and PNG, without AutoCAD.`,
    `DWG e DXF di AutoCAD: convertili tra loro o in PDF, SVG e PNG, senza AutoCAD.`],
  [`AutoCAD drawing`, `Disegno AutoCAD`],
  [`DWG is AutoCAD's native drawing format and the most common CAD file in architecture and engineering. Without AutoCAD or a DWG viewer it is hard to open or share.`,
    `DWG è il formato di disegno nativo di AutoCAD e il file CAD più comune in architettura e ingegneria. Senza AutoCAD o un visualizzatore DWG è difficile aprirlo o condividerlo.`],
  [`Drawing Exchange Format`, `Drawing Exchange Format`],
  [`DXF (Drawing Exchange Format) is Autodesk's interchange format for CAD drawings. Laser cutters, CNC software and most CAD programs read it, so it is the usual way to move drawings between tools.`,
    `DXF (Drawing Exchange Format) è il formato di interscambio di Autodesk per i disegni CAD. Lo leggono le macchine di taglio laser, i software CNC e la maggior parte dei programmi CAD, quindi è il modo abituale di spostare disegni tra strumenti.`],

  // 3D
  [`3D models`, `Modelli 3D`],
  [`3D models [in running text]`, `modelli 3D`],
  [`GLB, glTF, STL, OBJ, 3MF and PLY into each other, and FBX into any of them, with colours, textures and materials where the format keeps them, and to a shaded PNG or JPG picture. Nothing to install.`,
    `GLB, glTF, STL, OBJ, 3MF e PLY tra loro, e FBX in uno qualsiasi di essi, con colori, texture e materiali dove il formato li mantiene, e in un'immagine PNG o JPG ombreggiata. Niente da installare.`],
  [`glTF binary (GLB)`, `glTF binario (GLB)`],
  [`GLB is the one-file version of glTF, the 3D format of the web, AR and game engines. Meshes, materials and textures are packed into a single compact file.`,
    `GLB è la versione in un unico file di glTF, il formato 3D del web, della realtà aumentata e dei motori di gioco. Mesh, materiali e texture sono racchiusi in un unico file compatto.`],
  [`STL 3D model`, `Modello 3D STL`],
  [`STL is the classic file for 3D printing. It stores only the triangles of a shape, with no colours or units, and every slicer and CAD program reads it.`,
    `STL è il file classico della stampa 3D. Contiene solo i triangoli di una forma, senza colori né unità di misura, e ogni slicer e programma CAD lo legge.`],
  [`Wavefront OBJ model`, `Modello Wavefront OBJ`],
  [`OBJ (Wavefront) is a plain-text 3D format almost every 3D program opens. Materials and textures sit next to it in an .mtl file and pictures.`,
    `OBJ (Wavefront) è un formato 3D in testo semplice che quasi ogni programma 3D apre. Materiali e texture stanno accanto, in un file .mtl e nelle immagini.`],

  // Fonts
  [`Fonts`, `Font`],
  [`fonts`, `font`],
  [`Desktop and web fonts: TTF, OTF, WOFF, WOFF2 and EOT into each other.`,
    `Font per desktop e web: TTF, OTF, WOFF, WOFF2 ed EOT tra loro.`],
  [`TrueType font`, `Font TrueType`],
  [`TTF (TrueType) is the most common desktop font format on Windows and macOS. Install it to use the font in any app.`,
    `TTF (TrueType) è il formato di font per desktop più comune su Windows e macOS. Installalo per usare il font in qualsiasi app.`],
  [`OpenType font`, `Font OpenType`],
  [`OTF (OpenType) is a font format by Adobe and Microsoft. OpenType fonts with PostScript (CFF) outlines are common for professional typefaces and support features such as ligatures.`,
    `OTF (OpenType) è un formato di font di Adobe e Microsoft. I font OpenType con contorni PostScript (CFF) sono comuni tra i caratteri professionali e supportano funzioni come le legature.`],
  [`Web font (WOFF2)`, `Font web (WOFF2)`],
  [`WOFF2 is the compressed web font format supported by all modern browsers. It is typically about 30 % smaller than WOFF, so pages load faster.`,
    `WOFF2 è il formato compresso di font web supportato da tutti i browser moderni. Di solito è circa il 30 % più piccolo di WOFF, quindi le pagine si caricano più in fretta.`],

  // Geospatial
  [`Geospatial data`, `Dati geospaziali`],
  [`geospatial data`, `dati geospaziali`],
  [`Maps and GPS data: GeoJSON, KML, KMZ, GPX and Shapefile into each other and to CSV, Excel and JSON, and a CSV with coordinates back into a map file. Vector data only (points, lines and areas), always saved in longitude and latitude. Nothing to install.`,
    `Mappe e dati GPS: GeoJSON, KML, KMZ, GPX e Shapefile tra loro e in CSV, Excel e JSON, e un CSV con coordinate di nuovo in un file di mappa. Solo dati vettoriali (punti, linee e aree), sempre salvati in longitudine e latitudine. Niente da installare.`],
  [`one row per feature, with its coordinates`, `una riga per elemento, con le sue coordinate`],
  [`a CSV with longitude and latitude columns or WKT`, `un CSV con colonne di longitudine e latitudine o WKT`],

  // Camera RAW
  [`Camera RAW photo`, `Foto RAW della fotocamera`],
  [`Camera RAW files (CR2, CR3, NEF, ARW, DNG, RAF, ORF and more) hold the unprocessed sensor data of a photo. They keep the most detail for editing but are large and need special software to view.`,
    `I file RAW delle fotocamere (CR2, CR3, NEF, ARW, DNG, RAF, ORF e altri) contengono i dati del sensore non elaborati di una foto. Conservano il massimo dettaglio per la modifica, ma sono grandi e servono programmi appositi per vederli.`],

  // Conversion guides
  [`JPG is the safe choice when a website, an older Windows app or someone without an iPhone needs your photos. A whole batch of HEIC photos converts at once, and each JPG is saved next to its original.`,
    `JPG è la scelta sicura quando un sito web, una vecchia app di Windows o qualcuno senza iPhone ha bisogno delle tue foto. Un intero gruppo di foto HEIC si converte in una volta e ogni JPG viene salvato accanto al suo originale.`],
  [`Choose PNG when you want to keep editing the photo without adding a round of JPG compression. PNG is lossless, so expect files several times larger than the HEIC original.`,
    `Scegli PNG quando vuoi continuare a modificare la foto senza aggiungere un giro di compressione JPG. PNG è senza perdita, quindi aspettati file parecchie volte più grandi dell'originale HEIC.`],

  // Conversion guides
  [`HEIC keeps a photo in about half the space of a JPG at the same quality, the way iPhones save photos. Saving HEIC needs the free FFmpeg engine (about 100 MB, downloaded once in the app). EXIF, the colour profile and the orientation are kept.`,
    `HEIC conserva una foto in circa metà dello spazio di un JPG a parità di qualità, come fanno gli iPhone. Per salvare in HEIC serve il motore gratuito FFmpeg (circa 100 MB, scaricato una volta nell'app). EXIF, profilo colore e orientamento vengono mantenuti.`],
  [`Images saved from websites are often WebP. Converting to PNG keeps the full quality and any transparency, so the result works in every editor, slide deck and document.`,
    `Le immagini salvate dai siti web sono spesso WebP. Convertirle in PNG mantiene la qualità piena e l'eventuale trasparenza, così il risultato funziona in ogni editor, presentazione e documento.`],
  [`Pick JPG when the image is a photo and file size matters, for example for upload forms that reject WebP.`,
    `Scegli JPG quando l'immagine è una foto e conta la dimensione del file, per esempio per i moduli di caricamento che rifiutano WebP.`],
  [`Screenshots and exported photos saved as PNG can be many megabytes. Photos usually get much smaller as JPG; for text-heavy screenshots and logos, PNG often stays the better format.`,
    `Screenshot e foto esportate salvati come PNG possono pesare molti megabyte. Le foto di solito diventano molto più piccole in JPG; per screenshot con molto testo e per i loghi, PNG resta spesso il formato migliore.`],
  [`Converting JPG to PNG doesn't bring back detail lost to JPG compression, but it stops further loss: every later edit and save stays lossless. Convert before you retouch an image or add transparency in an editor.`,
    `Convertire JPG in PNG non recupera i dettagli persi con la compressione JPG, ma ferma ulteriori perdite: ogni modifica e salvataggio successivo resta senza perdita. Converti prima di ritoccare un'immagine o aggiungere trasparenza in un editor.`],
  [`AVIF images from modern websites and phones don't open in many older programs, image viewers and upload forms. JPG opens everywhere, at the cost of somewhat larger files.`,
    `Le immagini AVIF dei siti web moderni e dei telefoni non si aprono in molti programmi più vecchi, visualizzatori di immagini e moduli di caricamento. JPG si apre ovunque, al prezzo di file un po' più grandi.`],
  [`WebP is ideal for websites: photos get much smaller than JPG and graphics keep their transparency. The WEBP preset saves at quality 85, a good balance for the web.`,
    `WebP è ideale per i siti web: le foto diventano molto più piccole che in JPG e la grafica mantiene la trasparenza. Il preset WEBP salva con qualità 85, un buon equilibrio per il web.`],
  [`Scanned pages, receipts and photos of documents often have to be sent as one PDF. Drop the images on the merge preset to get a single PDF, or on PDF to get one PDF per image. By default each page takes the size of its image.`,
    `Pagine scansionate, scontrini e foto di documenti spesso vanno inviati come un unico PDF. Rilascia le immagini sul preset di unione per avere un solo PDF, oppure su PDF per avere un PDF per immagine. Per impostazione predefinita ogni pagina prende le dimensioni della sua immagine.`],
  [`One ICO covers everything Windows needs for desktop, Explorer and taskbar icons, and it works as a website favicon too. Start from a square PNG of at least 256×256 px for the sharpest result.`,
    `Un solo ICO copre tutto ciò che serve a Windows per le icone del desktop, di Esplora file e della barra delle applicazioni, e funziona anche come favicon di un sito web. Parti da un PNG quadrato di almeno 256×256 px per il risultato più nitido.`],
  [`Making a Mac app icon on Windows usually needs extra tools; Filee turns a PNG into an ICNS file directly. Use a square 1024×1024 px PNG so the Retina sizes stay sharp.`,
    `Creare l'icona di un'app per Mac su Windows di solito richiede strumenti aggiuntivi; Filee trasforma direttamente un PNG in un file ICNS. Usa un PNG quadrato di 1024×1024 px perché le dimensioni Retina restino nitide.`],
  [`Share a Photoshop design with people who don't have Photoshop: the PNG shows the image as saved, with the visible layers combined and transparency kept. PNG can't store layers, so keep the PSD for editing.`,
    `Condividi un progetto Photoshop con chi non ha Photoshop: il PNG mostra l'immagine come è stata salvata, con i livelli visibili uniti e la trasparenza mantenuta. PNG non può contenere livelli, quindi tieni il PSD per le modifiche.`],
  [`Filee reads the RAW files of Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One and more, and develops them with default settings. It's the quick way to get shareable JPGs from a shoot; for creative editing, use a RAW editor first.`,
    `Filee legge i file RAW di Canon, Nikon, Sony, Fujifilm, Olympus/OM System, Panasonic, Pentax, Samsung, Leica, Hasselblad, Phase One e altri, e li sviluppa con le impostazioni predefinite. È il modo rapido per avere JPG da condividere dopo uno scatto; per una modifica creativa, usa prima un editor RAW.`],
  [`Drop a whole memory card's worth of CR2 files at once: Filee converts them in parallel and saves each JPG next to its RAW file. Newer Canon cameras write CR3, which Filee reads as well.`,
    `Rilascia in una volta i CR2 di un'intera scheda di memoria: Filee li converte in parallelo e salva ogni JPG accanto al suo file RAW. Le fotocamere Canon più recenti scrivono CR3, che Filee legge ugualmente.`],
  [`NEF files are too large and too unusual to send as they are. As JPG they become small, universally viewable photos; use JPG 70 % or a half-size preset for messaging apps. Nikon's NRW files from Coolpix cameras work the same way.`,
    `I file NEF sono troppo grandi e troppo particolari per inviarli così come sono. In JPG diventano foto piccole e visibili ovunque; usa JPG 70 % o un preset Dimezza per le app di messaggistica. I file NRW delle fotocamere Coolpix di Nikon funzionano allo stesso modo.`],
  [`Many apps, slide decks and upload forms don't accept SVG. Filee renders the vector drawing to a PNG with transparency; compressed SVGZ files work too.`,
    `Molte app, presentazioni e moduli di caricamento non accettano SVG. Filee renderizza il disegno vettoriale in un PNG con trasparenza; funzionano anche i file SVGZ compressi.`],
  [`SVG to PDF stays vector: lines and text remain sharp at any zoom and in print, and the file stays small. Handy for sending logos and diagrams to a print shop or putting them into documents.`,
    `Da SVG a PDF resta vettoriale: linee e testo restano nitidi a qualsiasi zoom e in stampa, e il file resta piccolo. Comodo per inviare loghi e diagrammi in tipografia o inserirli nei documenti.`],
  [`EPS can only be displayed by a PostScript interpreter; Filee uses Ghostscript for that. The PDF keeps the vector artwork, so it opens anywhere and still prints sharply. PostScript (.ps) files work the same way.`,
    `EPS si può visualizzare solo con un interprete PostScript; Filee usa Ghostscript per questo. Il PDF mantiene la grafica vettoriale, quindi si apre ovunque e si stampa ancora in modo nitido. I file PostScript (.ps) funzionano allo stesso modo.`],
  [`Every page becomes its own JPG, so a 10-page PDF gives you 10 images. Handy for chats, slides and social posts that accept images but not PDF.`,
    `Ogni pagina diventa un JPG a sé, quindi un PDF di 10 pagine ti dà 10 immagini. Comodo per chat, slide e post sui social che accettano immagini ma non PDF.`],
  [`PNG keeps text and lines crisp without JPG artefacts, which suits slides, diagrams, sheet music and pages you want to annotate or put into a presentation.`,
    `PNG mantiene testo e linee nitidi senza gli artefatti del JPG, il che è adatto a slide, diagrammi, spartiti e pagine che vuoi annotare o inserire in una presentazione.`],
  [`Filee turns the PDF into a Word document with real paragraphs instead of page pictures, so you can fix typos or reuse the text. Complex layouts may need touch-ups, and a scanned PDF that only contains page images has no text to extract.`,
    `Filee trasforma il PDF in un documento Word con paragrafi veri invece di immagini delle pagine, così puoi correggere errori di battitura o riutilizzare il testo. Le impaginazioni complesse possono richiedere qualche ritocco, e un PDF scansionato che contiene solo immagini delle pagine non ha testo da estrarre.`],
  [`Filee goes PDF → Word → EPUB on its own, so the text reflows to fit a phone or an e-reader screen. It works best with PDFs that have real text in them. Headings come through as plain paragraphs, and scanned pages have no text to convert.`,
    `Filee passa da solo per PDF → Word → EPUB, così il testo si adatta allo schermo di un telefono o di un e-reader. Funziona meglio con PDF che contengono testo vero. I titoli arrivano come paragrafi semplici e le pagine scansionate non hanno testo da convertire.`],
  [`Filee takes the text of the PDF into a Word document, writes it as HWPX and then saves that as HWP, all with built-in engines. It works for PDFs with real text in them. Complex layouts may need touch-ups, and scanned pages have no text to take out.`,
    `Filee porta il testo del PDF in un documento Word, lo scrive come HWPX e poi lo salva come HWP, tutto con motori integrati. Funziona con PDF che contengono testo vero. Le impaginazioni complesse possono richiedere qualche ritocco, e le pagine scansionate non hanno testo da estrarre.`],
  [`Filee turns the PDF into a Word document first and then into Markdown, keeping paragraphs, headings and bold text where it can tell them apart. Useful for notes, wikis or pasting the text into other tools. Scanned pages have no text to convert.`,
    `Filee trasforma prima il PDF in un documento Word e poi in Markdown, mantenendo paragrafi, titoli e grassetto dove riesce a distinguerli. Utile per note, wiki o per incollare il testo in altri strumenti. Le pagine scansionate non hanno testo da convertire.`],
  [`Korean offices often need documents in Hangul format. Filee converts the PDF's text into an HWPX file you can open and edit in Hancom Hangul, without Hancom Office for the conversion; turn it into HWP afterwards if a form requires the old format.`,
    `Gli uffici coreani spesso richiedono documenti in formato Hangul. Filee converte il testo del PDF in un file HWPX che puoi aprire e modificare in Hancom Hangul, senza Hancom Office per la conversione; trasformalo poi in HWP se un modulo richiede il vecchio formato.`],
  [`Handy when a PDF has to be shown in PowerPoint or added to an existing deck: every page becomes a slide that looks exactly like the PDF, and the page's text waits in the speaker notes. The slides are pictures, so to change the wording convert the PDF to DOCX instead.`,
    `Comodo quando un PDF va mostrato in PowerPoint o aggiunto a una presentazione esistente: ogni pagina diventa una slide identica al PDF, e il testo della pagina ti aspetta nelle note del relatore. Le slide sono immagini, quindi per cambiare il testo converti invece il PDF in DOCX.`],
  [`No Microsoft Word or LibreOffice needed: Filee reads the DOCX itself and lays out the pages with headers, footers, tables and pictures. Drop several documents on the merge preset to combine them into one PDF.`,
    `Non servono Microsoft Word né LibreOffice: Filee legge da solo il DOCX e impagina le pagine con intestazioni, piè di pagina, tabelle e immagini. Rilascia più documenti sul preset di unione per combinarli in un unico PDF.`],
  [`Old Word 97–2003 documents from archives, official forms or legacy systems become PDFs that open anywhere. The same engine also converts ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord and Apple Pages files.`,
    `I vecchi documenti di Word 97–2003 provenienti da archivi, moduli ufficiali o sistemi datati diventano PDF che si aprono ovunque. Lo stesso motore converte anche file ODT, RTF, WPS, WordPerfect, Lotus Word Pro, AbiWord e Apple Pages.`],
  [`Save e-mails as PDF for records, invoices or legal files: the PDF shows the sender, recipients, date, subject and message, and it opens anywhere without a mail app.`,
    `Salva le e-mail come PDF per archivi, fatture o pratiche legali: il PDF mostra mittente, destinatari, data, oggetto e messaggio, e si apre ovunque senza un'app di posta.`],
  [`Filee renders HWP pages with rhwp, an open-source Hangul engine, so neither Hancom Office nor its approval dialog is involved. Useful for sending Korean documents to people who can't open HWP.`,
    `Filee renderizza le pagine HWP con rhwp, un motore Hangul open source, quindi non entrano in gioco né Hancom Office né la sua finestra di autorizzazione. Utile per inviare documenti coreani a chi non riesce ad aprire gli HWP.`],
  [`Turn a Hangul document into a Word file that colleagues abroad can edit. Text, paragraphs and tables are carried over; layouts with many floating objects are worth a quick check in Word.`,
    `Trasforma un documento Hangul in un file Word che i colleghi all'estero possono modificare. Testo, paragrafi e tabelle vengono trasferiti; le impaginazioni con molti oggetti mobili meritano un rapido controllo in Word.`],
  [`HWPX, the newer XML-based Hangul format, is converted like HWP: the built-in rhwp engine lays out the pages, fully offline. Handy for archiving HWPX forms from public institutions as PDF.`,
    `HWPX, il formato Hangul più recente basato su XML, si converte come HWP: il motore integrato rhwp impagina le pagine, completamente offline. Comodo per archiviare come PDF i moduli HWPX degli enti pubblici.`],
  [`Some systems and newer workflows accept only HWPX. Filee converts binary HWP to HWPX with rhwp, without Hancom Office, and converts a whole batch of old documents in one go.`,
    `Alcuni sistemi e flussi di lavoro più recenti accettano solo HWPX. Filee converte gli HWP binari in HWPX con rhwp, senza Hancom Office, e converte un intero gruppo di vecchi documenti in un colpo solo.`],
  [`Older versions of Hangul and some submission portals still expect .hwp. Filee converts HWPX back to HWP with rhwp, so you don't have to open and re-save each file in Hangul.`,
    `Le versioni più vecchie di Hangul e alcuni portali di invio richiedono ancora .hwp. Filee riconverte HWPX in HWP con rhwp, così non devi aprire e salvare di nuovo ogni file in Hangul.`],
  [`Filee's own HWPX writer carries the Word layout over: page size and margins, headers and footers with page numbers, tables with merged cells, borders and shading, text boxes, shapes and pictures. Every file it writes is checked with three independent HWPX readers in the tests.`,
    `Il writer HWPX di Filee trasferisce l'impaginazione di Word: dimensioni e margini della pagina, intestazioni e piè di pagina con i numeri di pagina, tabelle con celle unite, bordi e sfondi, caselle di testo, forme e immagini. Ogni file che scrive viene verificato nei test con tre lettori HWPX indipendenti.`],
  [`For offices and forms that still ask for .hwp. Filee writes the Word document as HWPX with its own writer and converts that to HWP with rhwp, both built in, so Hancom Office isn't needed for the conversion.`,
    `Per gli uffici e i moduli che chiedono ancora .hwp. Filee scrive il documento Word come HWPX con il proprio writer e lo converte in HWP con rhwp, entrambi integrati, quindi Hancom Office non serve per la conversione.`],
  [`Each page of the Word document becomes a JPG (Filee lays the document out as a PDF first), handy for posting a page online or sending a quick preview. Word isn't needed.`,
    `Ogni pagina del documento Word diventa un JPG (Filee impagina prima il documento come PDF), comodo per pubblicare una pagina online o inviare una rapida anteprima. Word non serve.`],
  [`Each visible sheet becomes its own section, with number formats, fonts, fills, borders and merged cells as Excel shows them. Wide sheets are scaled to the page width like Excel's "Fit all columns on one page", and frozen header rows repeat on every page.`,
    `Ogni foglio visibile diventa una sezione a sé, con formati numerici, font, riempimenti, bordi e celle unite come li mostra Excel. I fogli larghi vengono adattati alla larghezza della pagina come con "Adatta tutte le colonne a una pagina" di Excel, e le righe di intestazione bloccate si ripetono su ogni pagina.`],
  [`CSV holds a single table, so Filee writes one CSV per sheet. Cells are exported as values, ready for databases, scripts and import forms.`,
    `CSV contiene una sola tabella, quindi Filee scrive un CSV per foglio. Le celle vengono esportate come valori, pronte per database, script e moduli di importazione.`],
  [`An XLSX workbook can hold the formatting, formulas and extra sheets that CSV can't. Select all your CSV exports and drop them at once to get one workbook per file, without Excel's import dialog.`,
    `Una cartella di lavoro XLSX può contenere la formattazione, le formule e i fogli aggiuntivi che CSV non può contenere. Seleziona tutte le tue esportazioni CSV e rilasciale insieme per avere una cartella di lavoro per file, senza la finestra di importazione di Excel.`],
  [`Upgrade old Excel 97–2003 workbooks without Excel or LibreOffice: the conversion is built in. XLSX files are usually smaller, can't carry macros and open in every current spreadsheet app.`,
    `Aggiorna le vecchie cartelle di lavoro di Excel 97–2003 senza Excel né LibreOffice: la conversione è integrata. I file XLSX di solito sono più piccoli, non possono contenere macro e si aprono in ogni app di fogli di calcolo attuale.`],
  [`Each slide becomes one PDF page at the slide's size, with text, shapes, pictures, tables and the master design. Handy for handing out decks or uploading them where PowerPoint files aren't accepted. Animations and speaker notes aren't part of the PDF.`,
    `Ogni slide diventa una pagina PDF alle dimensioni della slide, con testo, forme, immagini, tabelle e il design dello schema. Comodo per distribuire presentazioni o caricarle dove i file PowerPoint non sono accettati. Animazioni e note del relatore non fanno parte del PDF.`],
  [`Old PowerPoint 97–2003 decks become PDFs that anyone can open, print or upload. Keynote (.key), ODP and WPS (DPS) presentations are converted the same way.`,
    `Le vecchie presentazioni di PowerPoint 97–2003 diventano PDF che chiunque può aprire, stampare o caricare. Le presentazioni Keynote (.key), ODP e WPS (DPS) si convertono allo stesso modo.`],
  [`Every slide becomes a JPG, ready for social posts, thumbnails, chat messages or a video editor. Choose PNG instead if the slides have lots of small text.`,
    `Ogni slide diventa un JPG, pronto per post sui social, miniature, messaggi in chat o un editor video. Scegli invece PNG se le slide hanno molto testo piccolo.`],
  [`Headings, lists (including task lists), tables, code, quotes, links, images, footnotes and math are laid out on A4 pages, without Pandoc, LaTeX or a browser. A quick way to share notes and README files with people who don't read Markdown.`,
    `Titoli, elenchi (compresi gli elenchi di attività), tabelle, codice, citazioni, link, immagini, note a piè di pagina e formule vengono impaginati su pagine A4, senza Pandoc, LaTeX né un browser. Un modo rapido per condividere note e file README con chi non legge il Markdown.`],
  [`Built in, no Pandoc needed. Headings, lists, tables, links and footnotes carry over, so you can keep editing and restyling the document in Word.`,
    `Integrato, non serve Pandoc. Titoli, elenchi, tabelle, link e note a piè di pagina vengono trasferiti, così puoi continuare a modificare il documento e cambiarne lo stile in Word.`],
  [`Plain text becomes a clean A4 PDF with one paragraph per line. Filee recognises UTF-8 and UTF-16 as well as legacy Korean (CP949) text files, so old logs and notes don't turn into garbled characters.`,
    `Il testo semplice diventa un PDF A4 pulito con un paragrafo per riga. Filee riconosce i file di testo UTF-8 e UTF-16 e quelli coreani nella vecchia codifica CP949, così vecchi log e note non diventano caratteri illeggibili.`],
  [`Save a web page or an HTML report as a PDF that looks the same everywhere and can be archived or printed. Filee converts .html files saved on your PC, and several of them can be merged into one PDF.`,
    `Salva una pagina web o un report HTML come PDF che appare uguale ovunque e si può archiviare o stampare. Filee converte i file .html salvati sul tuo PC, e più file si possono unire in un unico PDF.`],
  [`A PDF keeps a fixed page layout, which is handy for printing an e-book, reading it on a PC or sending it to a device without an EPUB reader.`,
    `Un PDF mantiene un'impaginazione fissa, il che è comodo per stampare un e-book, leggerlo su un PC o inviarlo a un dispositivo senza lettore EPUB.`],
  [`Move an old Kindle/Mobipocket library to EPUB so it opens in Apple Books, Google Play Books, Kobo and most reader apps. This direction is built in, so Calibre isn't needed.`,
    `Sposta una vecchia libreria Kindle/Mobipocket in EPUB perché si apra in Apple Books, Google Play Libri, Kobo e nella maggior parte delle app di lettura. Questa direzione è integrata, quindi Calibre non serve.`],
  [`The e-book tool Calibre writes the MOBI and AZW3 files. Current Kindles also accept EPUB through Send to Kindle, so MOBI is mainly useful for older Kindle devices and apps.`,
    `I file MOBI e AZW3 li scrive Calibre, lo strumento per e-book. I Kindle attuali accettano anche EPUB tramite Send to Kindle, quindi MOBI serve soprattutto per i dispositivi e le app Kindle più vecchi.`],
  [`Save the soundtrack of a lecture, concert or interview as an MP3 that plays everywhere: in the car, on an old player or in a transcription tool.`,
    `Salva l'audio di una lezione, di un concerto o di un'intervista come MP3 che si riproduce ovunque: in auto, su un vecchio lettore o in uno strumento di trascrizione.`],
  [`iPhone and Mac videos are MOV files. As MP4 they play on Android phones, smart TVs, older Windows apps and upload forms that reject MOV. The video and sound usually fit MP4 as they are, so Filee only rewraps them: no quality lost, HDR kept, done in seconds. The MP4 720p preset shrinks 4K clips for sharing.`,
    `I video di iPhone e Mac sono file MOV. In MP4 si riproducono su telefoni Android, smart TV, vecchie app di Windows e moduli di caricamento che rifiutano MOV. Video e audio di solito entrano in MP4 così come sono, quindi Filee li reimpacchetta soltanto: nessuna perdita di qualità, HDR mantenuto, fatto in pochi secondi. Il preset MP4 720p riduce le clip 4K per condividerle.`],
  [`MKV recordings, for example from OBS, often won't import into video editors or play on TVs, while MP4 is accepted almost everywhere. The conversion runs locally, so long recordings never have to be uploaded.`,
    `Le registrazioni MKV, per esempio di OBS, spesso non si importano negli editor video né si riproducono sulle TV, mentre MP4 è accettato quasi ovunque. La conversione avviene in locale, quindi le registrazioni lunghe non vanno mai caricate.`],
  [`Screen recordings and videos saved from the browser are often WebM, which many video editors, older players and messaging apps handle poorly. MP4 plays almost everywhere, and a whole batch of clips converts at once.`,
    `Le registrazioni dello schermo e i video salvati dal browser sono spesso WebM, che molti editor video, lettori più vecchi e app di messaggistica gestiscono male. MP4 si riproduce quasi ovunque, e un intero gruppo di clip si converte in una volta.`],
  [`Turn a short clip into an animated GIF for chats, documentation or bug reports. Keep it short: GIF stores every frame as a 256-colour image, so long or high-resolution videos make very large files.`,
    `Trasforma una breve clip in una GIF animata per chat, documentazione o segnalazioni di bug. Tienila breve: GIF salva ogni fotogramma come immagine a 256 colori, quindi video lunghi o ad alta risoluzione creano file molto grandi.`],
  [`A video dropped on JPG gives one still picture. To pick a thumbnail or go through a clip frame by frame, use the Extract frames (JPG) preset: the pictures land in a folder next to the video, every frame or every Nth. A video that would give more than 100,000 pictures or fill the disk is refused before it starts.`,
    `Un video rilasciato su JPG dà un solo fotogramma. Per scegliere una miniatura o scorrere una clip fotogramma per fotogramma, usa il preset Estrai fotogrammi (JPG): le immagini finiscono in una cartella accanto al video, ogni fotogramma o uno ogni N. Un video che darebbe più di 100.000 immagini o riempirebbe il disco viene rifiutato prima di iniziare.`],
  [`AVI files from old camcorders and cameras are large and often use codecs that phones and TVs no longer play. An MP4 with modern compression is usually much smaller and plays everywhere.`,
    `I file AVI delle vecchie videocamere e fotocamere sono grandi e usano spesso codec che telefoni e TV non riproducono più. Un MP4 con compressione moderna di solito è molto più piccolo e si riproduce ovunque.`],
  [`A WAV recording takes about 10 MB per minute; as MP3 it needs a fraction of that and still plays on every device.`,
    `Una registrazione WAV occupa circa 10 MB al minuto; in MP3 ne serve una frazione e si riproduce comunque su ogni dispositivo.`],
  [`Keep your lossless FLAC library at home and put MP3 copies on the phone, a USB stick for the car or an older player that doesn't play FLAC. Whole albums convert in one go.`,
    `Tieni a casa la tua libreria FLAC senza perdita e metti copie MP3 sul telefono, su una chiavetta USB per l'auto o su un vecchio lettore che non riproduce FLAC. Album interi si convertono in un colpo solo.`],
  [`iPhone voice memos, DRM-free iTunes downloads and many recorders produce M4A. MP3 is accepted by every player, car stereo and upload form.`,
    `I memo vocali di iPhone, i download di iTunes senza DRM e molti registratori producono M4A. MP3 è accettato da ogni lettore, autoradio e modulo di caricamento.`],
  [`Repack RAR archives as ZIP for people, upload forms and systems that only accept ZIP. WinRAR isn't needed, neither to read the RAR nor to write the ZIP.`,
    `Ricomprimi gli archivi RAR come ZIP per persone, moduli di caricamento e sistemi che accettano solo ZIP. WinRAR non serve, né per leggere il RAR né per scrivere lo ZIP.`],
  [`7Z often compresses better, but ZIP opens on any computer or phone without extra software. Convert when you send an archive to someone who doesn't have 7-Zip.`,
    `7Z spesso comprime meglio, ma ZIP si apre su qualsiasi computer o telefono senza software aggiuntivo. Converti quando invii un archivio a qualcuno che non ha 7-Zip.`],
  [`Send drawings to clients, site teams or print shops who don't have AutoCAD: a PDF opens on any PC or phone. Several drawings can be merged into one PDF.`,
    `Invia disegni a clienti, squadre di cantiere o tipografie che non hanno AutoCAD: un PDF si apre su qualsiasi PC o telefono. Più disegni si possono unire in un unico PDF.`],
  [`DXF files from CAD programs, laser-cutting jobs or design exchanges become PDFs anyone can open and print. SVG and PNG are available too, for example for web previews.`,
    `I file DXF dei programmi CAD, dei lavori di taglio laser o degli scambi di progetti diventano PDF che chiunque può aprire e stampare. Ci sono anche SVG e PNG, per esempio per le anteprime web.`],
  [`DXF is the interchange format that laser cutters, CNC software and most CAD programs read. Converting DWG to DXF lets you open AutoCAD drawings in those tools, and DXF back to DWG works too.`,
    `DXF è il formato di interscambio che leggono le macchine di taglio laser, i software CNC e la maggior parte dei programmi CAD. Convertire DWG in DXF ti permette di aprire i disegni AutoCAD in quegli strumenti, e funziona anche da DXF a DWG.`],
  [`Self-host a font on your website: WOFF2 is the compressed web font format every modern browser supports, typically about 30 % smaller than WOFF. Check that the font's license allows web embedding.`,
    `Ospita un font sul tuo sito web: WOFF2 è il formato compresso di font web supportato da ogni browser moderno, di solito circa il 30 % più piccolo di WOFF. Verifica che la licenza del font consenta l'incorporamento sul web.`],
  [`Some older programs, cutting and embroidery machines and game engines only accept TrueType fonts. Convert a whole OTF font family to TTF in one go, without a font editor.`,
    `Alcuni programmi più vecchi, macchine da taglio e da ricamo e motori di gioco accettano solo font TrueType. Converti un'intera famiglia di font OTF in TTF in un colpo solo, senza un editor di font.`],
  [`Use Line art to SVG for logos, signatures and scans: the ink becomes one black shape on a transparent background. Trace to SVG keeps up to 64 colours for icons and illustrations. Photos come out as flat patches, so tracing suits drawings best.`,
    `Usa Disegno al tratto in SVG per loghi, firme e scansioni: l'inchiostro diventa un'unica forma nera su sfondo trasparente. Vettorializza in SVG mantiene fino a 64 colori per icone e illustrazioni. Le foto escono come macchie di colore piatte, quindi la vettorializzazione è più adatta ai disegni.`],
  [`A JPG of a logo or a scanned sketch becomes an SVG that stays sharp at any size, ready for a cutting plotter, a website or a print shop. JPG noise turns into specks, so lower the Detail setting in the preset if the result looks busy.`,
    `Il JPG di un logo o di uno schizzo scansionato diventa un SVG che resta nitido a qualsiasi dimensione, pronto per un plotter da taglio, un sito web o una tipografia. Il rumore del JPG diventa macchioline, quindi abbassa l'impostazione Dettaglio nel preset se il risultato appare confuso.`],
  [`Laser cutters, CNC software and CAD programs read DXF. Filee writes the SVG's outlines in millimetres, so a shape 100 mm wide stays 100 mm. Curves become fine polylines. Fills, images and filters are left out.`,
    `Le macchine di taglio laser, i software CNC e i programmi CAD leggono DXF. Filee scrive i contorni dell'SVG in millimetri, quindi una forma larga 100 mm resta di 100 mm. Le curve diventano polilinee fini. Riempimenti, immagini e filtri vengono tralasciati.`],
  [`E-mails dragged out of Outlook are MSG files that only Outlook opens. As PDF they keep the sender, recipients, date, subject and message, and open anywhere. Outlook isn't needed.`,
    `Le e-mail trascinate fuori da Outlook sono file MSG che apre solo Outlook. In PDF mantengono mittente, destinatari, data, oggetto e messaggio, e si aprono ovunque. Outlook non serve.`],
  [`YAML is easier to read and edit by hand, which is why config files use it. Keys keep their order, and text that would read back as a number or true/false is quoted.`,
    `YAML è più facile da leggere e modificare a mano, ed è per questo che i file di configurazione lo usano. Le chiavi mantengono il loro ordine, e il testo che verrebbe riletto come numero o come true/false viene messo tra virgolette.`],
  [`Turn a config file into JSON for an API, a script or a tool that only reads JSON. Anchors and aliases are resolved, and a file with several documents becomes one array. Comments are dropped, since JSON has none.`,
    `Trasforma un file di configurazione in JSON per un'API, uno script o uno strumento che legge solo JSON. Ancore e alias vengono risolti, e un file con più documenti diventa un unico array. I commenti vengono eliminati, perché JSON non ne ha.`],
  [`A JSON list of records becomes a table you can open in Excel: one row per record, one column per key. A wrapper like {"users": […]} is looked through. Data that isn't a table stops with a message instead of a broken file.`,
    `Un elenco JSON di record diventa una tabella che puoi aprire in Excel: una riga per record, una colonna per chiave. Un contenitore come {"users": […]} viene attraversato. I dati che non sono una tabella si fermano con un messaggio invece di dare un file rotto.`],
  [`Get an address book into Excel or a mailing tool: one row per contact with name, organization, email, phone, address and birthday. Contacts from old Korean phones in CP949 are read correctly.`,
    `Porta una rubrica in Excel o in uno strumento di mailing: una riga per contatto con nome, organizzazione, e-mail, telefono, indirizzo e compleanno. I contatti dei vecchi telefoni coreani in CP949 vengono letti correttamente.`],
  [`Web players and online course platforms want WebVTT. Timing, line breaks and italics come across, and no engine is needed.`,
    `I lettori web e le piattaforme di corsi online vogliono WebVTT. Tempi, a capo e corsivo vengono trasferiti, e non serve nessun motore.`],
  [`Many players, TVs and editors don't read SMI, and old Korean SMI files often show as broken text. Filee detects CP949, picks the language with the most lines and saves a clean UTF-8 SRT.`,
    `Molti lettori, TV ed editor non leggono SMI, e i vecchi file SMI coreani appaiono spesso come testo illeggibile. Filee riconosce CP949, sceglie la lingua con più righe e salva un SRT pulito in UTF-8.`],
  [`When a TV, a phone or a video site refuses styled ASS subtitles, plain SRT works. Bold, italics, underline and colours are kept; positions, fonts and effects are dropped.`,
    `Quando una TV, un telefono o un sito di video rifiuta i sottotitoli ASS con stili, un SRT semplice funziona. Grassetto, corsivo, sottolineato e colori vengono mantenuti; posizioni, font ed effetti vengono eliminati.`],
  [`Take the subtitles out of a film to edit or translate them. The first text subtitle track is saved as SRT; picture-based subtitles (DVD, Blu-ray) can't be turned into text. Needs the free FFmpeg engine.`,
    `Estrai i sottotitoli da un film per modificarli o tradurli. La prima traccia di sottotitoli testuali viene salvata come SRT; i sottotitoli basati su immagini (DVD, Blu-ray) non si possono trasformare in testo. Richiede il motore gratuito FFmpeg.`],
  [`Open a print file in a 3D program that prefers OBJ. STL has no units, so Filee reads it as millimetres and writes OBJ in millimetres too, with Y pointing up like most 3D programs.`,
    `Apri un file di stampa in un programma 3D che preferisce OBJ. STL non ha unità di misura, quindi Filee lo legge in millimetri e scrive anche l'OBJ in millimetri, con l'asse Y verso l'alto come la maggior parte dei programmi 3D.`],
  [`Slicers for 3D printers take STL. Faces of any shape are split into triangles, and Y-up becomes Z-up, so an upright model stands on the print bed. STL keeps only the shape, so colours and textures stay in the OBJ.`,
    `Gli slicer per le stampanti 3D accettano STL. Le facce di qualsiasi forma vengono divise in triangoli e l'asse Y verso l'alto diventa Z verso l'alto, così un modello in piedi poggia sul piano di stampa. STL mantiene solo la forma, quindi colori e texture restano nell'OBJ.`],
  [`Bring a model from the web or a game engine into a program that reads OBJ. The .mtl file and the textures are written next to the .obj, so keep them together.`,
    `Porta un modello dal web o da un motore di gioco in un programma che legge OBJ. Il file .mtl e le texture vengono scritti accanto al file .obj, quindi tienili insieme.`],

  // FAQ
  [`Is Filee really free?`, `Filee è davvero gratuito?`],
  [`Yes. Filee is free and open source under the MIT license: no ads, no watermarks, no account, no trial and no file-count or file-size limits of its own.`,
    `Sì. Filee è gratuito e open source con licenza MIT: niente pubblicità, niente filigrane, nessun account, nessuna prova a tempo e nessun limite proprio al numero o alla dimensione dei file.`],
  [`Does it work offline? Are my files uploaded?`, `Funziona offline? I miei file vengono caricati?`],
  [`Every conversion runs on your own PC and files are never uploaded. The internet is only used to download an optional engine or check for updates, so confidential documents, photos and recordings stay on your computer.`,
    `Ogni conversione avviene sul tuo PC e i file non vengono mai caricati. Internet serve solo per scaricare un motore facoltativo o cercare aggiornamenti, quindi documenti riservati, foto e registrazioni restano sul tuo computer.`],
  [`Which file formats does Filee support?`, `Quali formati di file supporta Filee?`],
  [`Filee reads {formatTotal} file formats in {categoryCount} categories: {categoryList}. {builtinTotal} of them work right after install; the others use a free optional engine. The format catalog lists every format and what it converts to.`,
    `Filee legge {formatTotal} formati di file in {categoryCount} categorie: {categoryList}. {builtinTotal} funzionano subito dopo l'installazione; gli altri usano un motore facoltativo gratuito. Il catalogo dei formati elenca ogni formato e in cosa si converte.`],
  [`Do I need Microsoft Office, Hancom Office or LibreOffice?`,
    `Servono Microsoft Office, Hancom Office o LibreOffice?`],
  [`No. Word, Excel and PowerPoint files (DOCX, XLSX, XLS, CSV, PPTX) and Korean HWP/HWPX documents are converted by engines built into Filee. Filee doesn't use Office or Hancom Office even when they are installed; LibreOffice is only an optional in-app download for older formats such as DOC, PPT, ODT and RTF. Text that needs shaping (Arabic, Hebrew, Indic scripts, Thai and others) is the exception: DOCX, TXT, Markdown, HTML, XLSX, PPTX and HWPX files with it go to PDF and images through the optional LibreOffice engine. Without LibreOffice, that file fails with a message naming the script instead of becoming a broken PDF.`,
    `No. I file Word, Excel e PowerPoint (DOCX, XLSX, XLS, CSV, PPTX) e i documenti coreani HWP/HWPX vengono convertiti da motori integrati in Filee. Filee non usa Office né Hancom Office nemmeno quando sono installati; LibreOffice è solo un download facoltativo nell'app per formati più vecchi come DOC, PPT, ODT e RTF. Fa eccezione il testo che richiede lo shaping dei glifi (arabo, ebraico, scritture indiane, thai e altre): i file DOCX, TXT, Markdown, HTML, XLSX, PPTX e HWPX che lo contengono passano a PDF e immagini con il motore facoltativo LibreOffice. Senza LibreOffice la conversione di quel file non riesce e un messaggio indica la scrittura, invece di produrre un PDF difettoso.`],
  [`What are the optional engines?`, `Cosa sono i motori facoltativi?`],
  [`Large engines are not in the installer. Tick them on the installer's engine page, or download them inside Filee whenever you need them: {engineDetails}. They are saved in Filee's own folder and can be removed at any time, and the app shows their versions, download speed and time left. If FFmpeg, calibre, Pandoc, Ghostscript or LibreOffice is already on your PC (on the PATH, Scoop included, or in Program Files), Filee uses it and skips the download, and says when that copy is older than the version it is tested with. Settings → Engines → Use my copy picks a specific one.`,
    `I motori di grandi dimensioni non sono nel programma di installazione. Selezionali nella pagina dei motori del programma di installazione, oppure scaricali dentro Filee quando ti servono: {engineDetails}. Vengono salvati nella cartella di Filee e si possono rimuovere in qualsiasi momento, e l'app mostra le loro versioni, la velocità di download e il tempo rimanente. Se FFmpeg, calibre, Pandoc, Ghostscript o LibreOffice è già sul tuo PC (nel PATH, anche tramite Scoop, o in Programmi), Filee lo usa e salta il download, e ti avvisa quando quella copia è più vecchia della versione con cui è testato. Impostazioni → Motori → Usa la mia copia… ne sceglie uno preciso.`],
  [`Does installing Filee need administrator rights?`, `L'installazione di Filee richiede i diritti di amministratore?`],
  [`Only once, while installing. The installer puts Filee in Program Files for all users and, on Windows 11, adds “Convert with Filee” to the top of the File Explorer menu. Filee itself then runs as your normal user. For silent installs, run the installer with /VERYSILENT /SUPPRESSMSGBOXES. If you can't install programs, use the portable ZIP: unzip it anywhere and run Filee.exe.`,
    `Solo una volta, durante l'installazione. Il programma di installazione mette Filee in Programmi per tutti gli utenti e, su Windows 11, aggiunge “Converti con Filee” in cima al menu di Esplora file. Filee poi funziona con il tuo utente normale. Per un'installazione silenziosa, esegui il programma di installazione con /VERYSILENT /SUPPRESSMSGBOXES. Se non puoi installare programmi, usa lo ZIP portable: estrailo dove vuoi ed esegui Filee.exe.`],
  [`Filee doesn't start on Windows 10: no window, no error. What can I do?`,
    `Filee non si avvia su Windows 10: nessuna finestra, nessun errore. Cosa posso fare?`],
  [`This happens on a Windows 10 that hasn't been updated for a long time, on a PC whose processor supports Hardware-enforced Stack Protection (CET). Windows turns that protection on but lacks a part that .NET needs, so Filee and its installer stop right away, without a window or a message. Installing the available Windows updates (the latest cumulative update) fixes it. If updating isn't possible, turning the protection off for Filee alone usually works: in PowerShell as administrator, run Set-ProcessMitigation -Name Filee.exe -Disable UserShadowStack, then the same for filee-cli.exe and for the installer's file name (or use the portable ZIP). To undo it, remove those entries in Windows Security → App & browser control → Exploit protection settings → Program settings.`,
    `Succede su un Windows 10 che non viene aggiornato da molto tempo, su un PC il cui processore supporta la protezione dello stack applicata dall'hardware (CET). Windows attiva questa protezione ma gli manca una parte di cui .NET ha bisogno, quindi Filee e il suo programma di installazione si fermano subito, senza finestra né messaggio. Installare gli aggiornamenti di Windows disponibili (l'ultimo aggiornamento cumulativo) risolve il problema. Se aggiornare non è possibile, di solito funziona disattivare la protezione solo per Filee: in PowerShell come amministratore esegui Set-ProcessMitigation -Name Filee.exe -Disable UserShadowStack, poi lo stesso per filee-cli.exe e per il nome del file del programma di installazione (oppure usa lo ZIP portable). Per annullare, rimuovi quelle voci in Sicurezza di Windows → Controllo delle app e del browser → Impostazioni di Protezione dagli exploit → Impostazioni programma.`],
  [`Can I convert many files at once?`, `Posso convertire molti file in una volta?`],
  [`Yes. Select as many files as you like and drop them once: Filee converts them in parallel, a failed file never stops the others, and presets can merge everything into one PDF or pack it into one ZIP.`,
    `Sì. Seleziona quanti file vuoi e rilasciali una volta sola: Filee li converte in parallelo, un file non riuscito non ferma mai gli altri, e i preset possono unire tutto in un unico PDF o metterlo in un unico ZIP.`],
  [`Can I convert from the Windows 11 right-click menu?`,
    `Posso convertire dal menu del clic destro di Windows 11?`],
  [`Yes. Right-click files in File Explorer and choose "Convert with Filee". On Windows 11 you can also put it in the top-level menu, without "Show more options": click "Add to the main menu" in Settings → General once and approve the administrator prompt. Send To, a keyboard shortcut and the drop zone in the main window work too.`,
    `Sì. Fai clic destro sui file in Esplora file e scegli "Converti con Filee". Su Windows 11 puoi anche metterlo nel menu principale, senza "Mostra altre opzioni": fai clic una volta su "Aggiungi al menu principale" in Impostazioni → Generali e approva la richiesta di amministratore. Funzionano anche Invia a, una scorciatoia da tastiera e l'area di rilascio nella finestra principale.`],
  [`Can Filee convert from the command line or automatically?`,
    `Filee può convertire dalla riga di comando o in automatico?`],
  [`Yes. Setup can add the filee command to PATH: filee convert *.heic --to jpg converts files, wildcards and folders with your presets, prints JSON for scripts and returns exit codes. Watch folders automatically convert the files that land in a folder and can move the originals aside. Set them up on the Watch folders page in the app or with filee watch in a terminal.`,
    `Sì. L'installazione può aggiungere il comando filee al PATH: filee convert *.heic --to jpg converte file, caratteri jolly e cartelle con i tuoi preset, stampa JSON per gli script e restituisce codici di uscita. Le cartelle monitorate convertono in automatico i file che arrivano in una cartella e possono spostare da parte gli originali. Configurale nella pagina Cartelle monitorate dell'app o con filee watch in un terminale.`],
  [`How do I convert a file, for example HEIC to JPG?`, `Come converto un file, per esempio da HEIC a JPG?`],
  [`Select the files in File Explorer, hold Ctrl (or the key you chose) and drag them. A donut of formats opens at the cursor: drop the files on JPG and the new files appear next to the originals. There are step-by-step guides for the most common conversions.`,
    `Seleziona i file in Esplora file, tieni premuto Ctrl (o il tasto che hai scelto) e trascinali. Sul cursore si apre un donut di formati: rilascia i file su JPG e i nuovi file compaiono accanto agli originali. Per le conversioni più comuni ci sono guide passo passo.`],
  [`Why use Filee instead of an online converter?`, `Perché usare Filee invece di un convertitore online?`],
  [`Online converters upload your files to someone else's server, often limit file size and count, and depend on a fast connection. Filee converts on your PC: private files stay private, large videos and hundreds of files are no problem, and it works without internet, for free and without ads.`,
    `I convertitori online caricano i tuoi file sul server di qualcun altro, spesso limitano dimensione e numero dei file e dipendono da una connessione veloce. Filee converte sul tuo PC: i file privati restano privati, video grandi e centinaia di file non sono un problema, e funziona senza internet, gratis e senza pubblicità.`],
  [`Which operating systems are supported?`, `Quali sistemi operativi sono supportati?`],
  [`Windows 10 and 11 (64-bit) and Linux (x64 and ARM64, Ubuntu 22.04 or later) are full releases. On Linux the drag gesture needs an X11 session; on KDE Plasma with Wayland it is experimental, and on other Wayland desktops the drop zone and the file manager's right-click menu work. macOS 13 or later (Apple silicon and Intel) is a preview: the app isn't notarized yet, so macOS asks you to allow it once under Privacy & Security. Pick your system in the download section.`,
    `Windows 10 e 11 (64 bit) e Linux (x64 e ARM64, Ubuntu 22.04 o successivo) sono versioni complete. Su Linux il gesto di trascinamento richiede una sessione X11; su KDE Plasma con Wayland è sperimentale, e sugli altri desktop Wayland funzionano l'area di rilascio e il menu del clic destro del gestore file. macOS 13 o successivo (Apple silicon e Intel) è in anteprima: l'app non è ancora autenticata da Apple, quindi macOS ti chiede di consentirla una volta in Privacy e sicurezza. Scegli il tuo sistema nella sezione download.`],
]);
